if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

// Bedrock loads package classes through Composer. Standalone installs use the
// autoloader generated by running composer install in this plugin directory.
if ( ! class_exists( \Aeon\Plugin::class ) && is_readable( __DIR__ . '/vendor/autoload.php' ) ) {
	require_once __DIR__ . '/vendor/autoload.php';
}

if ( ! class_exists( \Aeon\Plugin::class ) ) {
	add_action(
		'admin_notices',
		static function () {
			if ( current_user_can( 'activate_plugins' ) ) {
				printf(
					'<div class="notice notice-error">
						<p>%s</p>
					</div>',
					esc_html__( 'Aeon requires its Composer autoloader. Run Composer install for the site or plugin.', 'aeon' )
				);
			}
		}
	);
	return;
}

// Load new Flux classes when a site's Composer classmap has not been refreshed yet.
if ( ! class_exists( \Aeon\Flux\Cli::class ) ) {
	foreach ( glob( __DIR__ . '/flux/*.php' ) as $flux_file ) {
		require_once $flux_file;
	}
}

register_activation_hook( __FILE__, array( \Aeon\Flux\Database::class, 'activate' ) );

require_once __DIR__ . '/functions-contact.php';

( new \Aeon\Plugin() )->register();
